import numpy as np

def laplace_numeric(f, s, T=50, n=200000):
    """Trapezium rule for the integral of exp(-s t) f(t) over [0, T]."""
    t = np.linspace(0, T, n + 1)
    g = np.exp(-s * t) * f(t)
    h = T / n
    return h * (g.sum() - (g[0] + g[-1]) / 2)

def pv_growing(c, g, r):
    """Value of c e^(g t) a year for ever, discounted at r."""
    if r <= g:
        raise ValueError("no value when r <= g")
    return c / (r - g)
